import type { RakazAuthUser, RakazIssuedCredentials } from './auth';
import type { RakazAdminCheckin, RakazWorkSchedule } from './checkin';
import type { RakazAbsenceReport, RakazGeoPoint, RakazTripEvent, RakazTripSnapshot, RakazTripStudentState } from './events';
import type { RakazPayment, RakazPaymentInput, RakazSubscription, RakazSubscriptionInput } from './finance';
import type { CanonicalStudentId, CanonicalTripId, RakazUid } from './ids';
import type { RakazTripPhase } from './mapping';
import type { RakazSupportContact, RakazSupportTicket, RakazTicketStatus } from './parent';
import type { RakazUnsubscribe } from './repositories';
/** Admin-managed student record (source of truth for both apps). */
export interface RakazAdminStudent {
    id: CanonicalStudentId;
    internalNumber: string;
    fullName: string;
    firstName: string;
    grade: string;
    stage: string;
    gender: 'male' | 'female' | null;
    birthDate: number | null;
    schoolId: string;
    schoolName: string;
    routeId: string | null;
    guardianUid: RakazUid | null;
    guardianName: string;
    guardianPhone: string;
    home: RakazGeoPoint;
    governorate: string;
    area: string;
    neighborhood: string;
    street: string;
    landmark: string;
    accessNotes: string;
    notes: string;
    active: boolean;
}
/** Fields the administration fills in. `id` is generated by the API when omitted. */
export type RakazAdminStudentInput = Omit<RakazAdminStudent, 'id' | 'schoolName' | 'routeId' | 'guardianUid'> & {
    id?: CanonicalStudentId;
};
export interface RakazAdminStudentResult {
    student: RakazAdminStudent;
    /** Present only when a new guardian account was created for this phone number. */
    guardianCredentials: RakazIssuedCredentials | null;
}
export interface RakazAdminDriver {
    uid: RakazUid;
    name: string;
    phone: string;
    vehicleLabel: string;
    plateNumber: string;
    vehicleModel: string;
    vehicleColor: string;
    vehicleCapacity: number | null;
    routeId: string | null;
    active: boolean;
}
export type RakazAdminDriverInput = Omit<RakazAdminDriver, 'uid' | 'routeId'>;
export interface RakazAdminDriverResult {
    driver: RakazAdminDriver;
    /** Present only when the account was just created. */
    credentials: RakazIssuedCredentials | null;
}
export interface RakazAdminGuardian {
    uid: RakazUid;
    name: string;
    phone: string;
    studentIds: CanonicalStudentId[];
    active: boolean;
    mustChangePassword: boolean;
}
export interface RakazAdminRouteStop {
    studentId: CanonicalStudentId;
    sequence: number;
    /** HH:mm */
    pickupTime: string;
    /** HH:mm */
    dropoffTime: string;
}
export interface RakazAdminRoute {
    /** Route code, e.g. R-204 */
    id: string;
    name: string;
    schoolId: string;
    driverUid: RakazUid | null;
    /** Where the bus starts the day; defaults to the school when null. */
    depot: RakazGeoPoint | null;
    stops: RakazAdminRouteStop[];
    active: boolean;
}
export type RakazAdminRouteInput = Omit<RakazAdminRoute, 'stops' | 'driverUid'>;
export interface RakazAdminSchool {
    id: string;
    name: string;
    address: string;
    locationLabel: string;
    coordinate: RakazGeoPoint;
    phone: string;
    /** HH:mm */
    startTime: string;
    /** HH:mm */
    endTime: string;
}
export type RakazAdminSchoolInput = Omit<RakazAdminSchool, 'id'> & {
    id?: string;
};
/** Dashboard overview counters. */
export interface RakazAdminOverview {
    activeTrips: number;
    studentsOnBoard: number;
    absencesToday: number;
    openHandovers: number;
    /** Active drivers that have no route assigned. */
    unassignedDrivers: number;
    emergenciesToday: number;
    openTickets: number;
    updatedAt: number;
}
/** A trip with its per-student breakdown, for the live trips page. */
export interface RakazAdminTrip extends RakazTripSnapshot {
    routeName: string;
    driverName: string | null;
    phase: RakazTripPhase;
    students: RakazTripStudentState[];
}
export interface RakazAdminFinanceRow {
    studentId: CanonicalStudentId;
    studentName: string;
    guardianName: string;
    guardianPhone: string;
    subscription: RakazSubscription | null;
    payments: RakazPayment[];
}
export interface RakazBroadcastInput {
    title: string;
    body: string;
    /** Who receives it. `route`/`students` narrow the guardians; `drivers` targets all drivers. */
    audience: 'guardians' | 'drivers' | 'everyone';
    studentIds?: CanonicalStudentId[];
    routeId?: string;
}
/** Admin / dashboard API — creates and supervises the data the mobile apps consume. */
export interface RakazAdminApi {
    getOverview(): Promise<RakazAdminOverview>;
    listSchools(): Promise<RakazAdminSchool[]>;
    saveSchool(school: RakazAdminSchoolInput): Promise<RakazAdminSchool>;
    deleteSchool(id: string): Promise<void>;
    listStudents(): Promise<RakazAdminStudent[]>;
    saveStudent(student: RakazAdminStudentInput): Promise<RakazAdminStudentResult>;
    deleteStudent(id: CanonicalStudentId): Promise<void>;
    listDrivers(): Promise<RakazAdminDriver[]>;
    createDriver(driver: RakazAdminDriverInput): Promise<RakazAdminDriverResult>;
    updateDriver(uid: RakazUid, driver: RakazAdminDriverInput): Promise<RakazAdminDriverResult>;
    deleteDriver(uid: RakazUid): Promise<void>;
    listGuardians(): Promise<RakazAdminGuardian[]>;
    resetPassword(uid: RakazUid): Promise<RakazIssuedCredentials>;
    listRoutes(): Promise<RakazAdminRoute[]>;
    saveRoute(route: RakazAdminRouteInput): Promise<RakazAdminRoute>;
    deleteRoute(id: string): Promise<void>;
    assignStudentToRoute(studentId: CanonicalStudentId, routeId: string | null, stop?: Partial<Omit<RakazAdminRouteStop, 'studentId'>>): Promise<void>;
    assignDriverToRoute(driverUid: RakazUid | null, routeId: string): Promise<void>;
    listTrips(dateISO?: string): Promise<RakazAdminTrip[]>;
    listTripEvents(tripId: CanonicalTripId): Promise<RakazTripEvent[]>;
    watchLiveTrips(onChange: (trips: RakazAdminTrip[]) => void, onError?: (error: unknown) => void): RakazUnsubscribe;
    /** Create today's morning/afternoon trip rows ahead of the driver's first event. */
    openDailyTrips(params: {
        routeId: string;
        dateISO?: string;
    }): Promise<{
        morningTripId: CanonicalTripId;
        afternoonTripId: CanonicalTripId;
    }>;
    listAbsences(params?: {
        dateISO?: string;
    }): Promise<RakazAbsenceReport[]>;
    broadcast(input: RakazBroadcastInput): Promise<{
        recipients: number;
    }>;
    listFinance(): Promise<RakazAdminFinanceRow[]>;
    saveSubscription(studentId: CanonicalStudentId, input: RakazSubscriptionInput): Promise<RakazSubscription>;
    recordPayment(studentId: CanonicalStudentId, input: RakazPaymentInput): Promise<RakazPayment>;
    listTickets(): Promise<RakazSupportTicket[]>;
    updateTicket(id: string, patch: {
        status: RakazTicketStatus;
        adminReply: string | null;
    }): Promise<RakazSupportTicket>;
    getSettings(): Promise<RakazSupportContact>;
    saveSettings(settings: RakazSupportContact): Promise<RakazSupportContact>;
    getWorkSchedule(): Promise<RakazWorkSchedule>;
    saveWorkSchedule(schedule: RakazWorkSchedule): Promise<RakazWorkSchedule>;
    /** Driver check-ins of one day (default today), newest first. */
    listCheckins(params?: {
        dateISO?: string;
        driverUid?: string;
    }): Promise<RakazAdminCheckin[]>;
}
export type { RakazAuthUser };
